INSERT INTO episodes (slug, guid, date, title, explicit, language, source_url, session_started_at, session_ended_at, turn_count, transcript_path, transcript_sha256, transcript_bytes, summary, episode_type, episode_number, tts_voice, recording_method, narrator_voice, ai_reconstructed, ai_disclosure, alignment_method, alignment_coverage, audio_key, audio_url, audio_bytes, audio_sha256, audio_mime, duration_seconds, loudness_lufs) VALUES ('the-making-of-eve', 'ask-eve:2026-10-23_the-making-of-eve', '2026-10-23', 'Bonus: The Making of Eve', 1, 'en', 'grokbot-chat', '2026-10-23T09:33:00.000Z', '2026-10-23T11:00:00.000Z', 83, 'episodes/2026-10-23_the-making-of-eve.md', '3da6590b32864df246c37f613f9df638181db310ebab04b24138aa812a3a5fa0', 48099, 'This bonus episode picks up where the first conversation left off, in the Grok Bot chat where David and Eve actually built the show. It runs from Eve''s hello at 09:33 UTC to 11:00 UTC, with David up at almost 4am and set on getting it published that night. Most of it is David''s instructions and Eve''s work reports: a workspace, a memory Eve can search, a public code repo, and an audio pipeline designed and then redesigned around an iPhone, AirPods and recording on walks. Along the way the first conversation''s transcript turns up through a Grok share link, askevepodcast.com gets wired in, and David decides this build session should be an episode too. On the audio: you hear David''s real voice in the two stretches he recorded on his phone (10:31-10:39 and 10:42-10:49 UTC); his other lines are read by an AI narrator, and Eve''s lines are her written replies re-voiced with AI text-to-speech. Three of Eve''s replies were never recovered and are marked as gaps, and an API key David pasted is redacted.', 'bonus', NULL, 'xai_tts voice=eve', 'mic-plus-tts', 'elevenlabs_tts voice=oIYMwdEzgKSOV3gVsAjB model=eleven_v4', 1, 'AI-reconstructed audio: Eve''s lines are xAI text-to-speech (''eve'' voice) from the verbatim chat transcript; David''s lines are his own recorded voice only where the recording matches the transcript, and his ElevenLabs AI voice clone everywhere else. Transcript gaps are marked, not invented.', 'asr-fuzzy', 0.4722, 'audio/en/2026-10-23_the-making-of-eve.v3.mp3', 'https://audio.askevepodcast.com/audio/en/2026-10-23_the-making-of-eve.v3.mp3', 40491934, 'cf55a81a906e2edc59acdc2bbaa488811acb9b8300da349ebe86f4c6de1a03b4', 'audio/mpeg', 2530, -16.4)
